<template><section class="section-card movement-config"><h2 class="section-title">Movement Training Group</h2><div class="section-body"><el-form-item label="Template"><el-select v-model="template" @change="applyTemplate"><el-option label="Studio movement workout (real videos)" value="studio"/><el-option label="Dumbbell upper body · vision" value="upper"/><el-option label="Full body foundations · vision" value="full"/><el-option label="Everyday movement · follow along" value="regular"/></el-select><div class="field-help">A template fills the step list below. Review the targets before publishing.</div></el-form-item><el-form-item label="Vision Recognition"><el-switch :value="value.vision.supported" @input="patchVision('supported',$event)"/><div class="field-help">Adds a Vision Recognition start button to the preparation page. Low-performance devices use Follow along.</div></el-form-item><el-form-item v-if="value.vision.supported" label="Required Framing"><el-radio-group :value="value.vision.framing" @input="patchVision('framing',$event)"><el-radio label="full_body">Full body</el-radio><el-radio label="upper_body">Upper body</el-radio></el-radio-group><div class="field-help">Sets the silhouette guidance for this group. The demo starts when a person stays in view for 3 seconds; complete-body framing is not required. Include full-body guidance for squat steps.</div></el-form-item><div v-for="(step,index) in value.steps" :key="index" class="movement-config__step"><div class="movement-config__row"><b>{{ index+1 }}</b><el-select :value="step.phase" aria-label="Training phase" @input="patchStep(index,'phase',$event)"><el-option v-for="p in phases" :key="p.value" :label="p.label" :value="p.value"/></el-select><el-select :value="step.exerciseId" aria-label="Exercise" @input="patchStep(index,'exerciseId',$event)"><el-option v-for="e in exercises" :key="e.id" :label="e.name" :value="e.id"/></el-select><el-button type="text" :disabled="value.steps.length<=1" @click="remove(index)">Remove</el-button></div><div class="movement-config__row"><span>Target</span><el-select :value="step.kind" aria-label="Target type" @input="patchStep(index,'kind',$event)"><el-option label="Repetitions" value="reps"/><el-option label="Seconds" value="time"/></el-select><admin-number :value="step.target" :min="1" :max="step.kind==='time'?600:100" :precision="0" @input="patchStep(index,'target',$event)"/><template v-if="step.kind==='reps'"><span>Default cadence (s)</span><admin-number :value="step.repSeconds" :min="1" :max="10" @input="patchStep(index,'repSeconds',$event)"/></template><template v-if="index<value.steps.length-1"><span>Scheduled rest (s)</span><admin-number :value="step.restSeconds||0" :min="0" :max="300" :precision="0" @input="patchStep(index,'restSeconds',$event)"/></template></div><el-input :value="step.videoUrl||''" placeholder="Optional HTTPS exercise video URL (MP4 / WebM)" @input="patchStep(index,'videoUrl',$event)"/></div><el-button icon="el-icon-plus" @click="add">Add step</el-button><el-alert v-if="errors.length" type="warning" :closable="false" :title="errors.join(' ')"/><p class="field-help">Rest follows the generated plan; 0 means the next movement starts without rest. Timed steps use the timer in either mode. Repetition steps in Vision recognition advance only on recognized repetitions. Skipping records the uncompleted portion separately.</p></div></section></template>
<script>
import {exercises,defaultTraining,validateTraining} from '../../../config/movement-training.cjs'
import AdminNumber from '@/components/AdminNumber'
export default {components:{AdminNumber},props:{value:{type:Object,required:true}},data(){return{exercises,template:'',phases:[{value:'warmup',label:'Warm-up'},{value:'main',label:'Workout'},{value:'cooldown',label:'Cooldown'}]}},computed:{errors(){return validateTraining(this.value)}},methods:{emit(value){this.$emit('input',value)},applyTemplate(value){this.emit(defaultTraining(value))},patchVision(key,value){this.emit({...this.value,vision:{...this.value.vision,[key]:value}})},patchStep(index,key,value){this.emit({...this.value,steps:this.value.steps.map((s,i)=>i===index?{...s,[key]:value}:s)})},remove(index){this.emit({...this.value,steps:this.value.steps.filter((s,i)=>i!==index)})},add(){this.emit({...this.value,steps:[...this.value.steps,{exerciseId:'shoulder_stretch',phase:'cooldown',kind:'time',target:20,repSeconds:4}]})}}}
</script>
<style scoped>.movement-config__step{padding:14px;background:#f7f9fc;border:1px solid #e1e6ed;border-radius:8px;margin-bottom:12px}.movement-config__row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px}.movement-config__row .el-select{width:185px}.movement-config__row>b{width:18px}.movement-config__row>span{font-size:12px;color:#606a78}.movement-config .el-alert{margin-top:16px}</style>
